/* Rounded select menus are rendered in a fixed layer so modal and page overflow
   can never clip them. The native select remains the source of truth. */
const roundedSelectPopover=document.createElement('div');
roundedSelectPopover.className='rounded-select-popover';
roundedSelectPopover.setAttribute('role','listbox');
document.body.appendChild(roundedSelectPopover);
let activeRoundedSelect=null;
function syncRoundedSelect(select){
 const trigger=select.parentElement?.querySelector('.rounded-select-trigger');
 if(!trigger)return;
 const option=select.options[select.selectedIndex];
 trigger.querySelector('span').textContent=option?.textContent?.trim()||'请选择';
 trigger.disabled=select.disabled;
}
function closeRoundedSelect(){
 roundedSelectPopover.classList.remove('open');
 activeRoundedSelect?.parentElement?.querySelector('.rounded-select-trigger')?.classList.remove('open');
 activeRoundedSelect=null;
}
function openRoundedSelect(select,trigger){
 closeRoundedSelect();
 syncRoundedSelect(select);
 activeRoundedSelect=select;
 roundedSelectPopover.innerHTML='';
 [...select.children].forEach(item=>{
  if(item.tagName==='OPTGROUP'){
   const label=document.createElement('div');label.className='rounded-select-group';label.textContent=item.label;roundedSelectPopover.appendChild(label);
   [...item.children].forEach(option=>appendRoundedOption(option,select));
  }else if(item.tagName==='OPTION')appendRoundedOption(item,select);
 });
 const rect=trigger.getBoundingClientRect(),maxHeight=Math.min(280,window.innerHeight-28),estimated=Math.min(maxHeight,roundedSelectPopover.childElementCount*38+12),spaceBelow=window.innerHeight-rect.bottom-10;
 roundedSelectPopover.style.width=`${Math.max(190,rect.width)}px`;
 roundedSelectPopover.style.left=`${Math.max(10,Math.min(rect.left,window.innerWidth-Math.max(190,rect.width)-10))}px`;
 roundedSelectPopover.style.top=`${spaceBelow>=Math.min(estimated,180)?rect.bottom+7:Math.max(10,rect.top-estimated-7)}px`;
 roundedSelectPopover.style.maxHeight=`${maxHeight}px`;
 roundedSelectPopover.classList.add('open');trigger.classList.add('open');
 roundedSelectPopover.querySelector('.selected')?.scrollIntoView({block:'nearest'});
}
function appendRoundedOption(option,select){
 const button=document.createElement('button');button.type='button';button.className='rounded-select-option';
 button.textContent=option.textContent.trim();button.dataset.value=option.value;button.disabled=option.disabled;
 button.classList.toggle('selected',option.selected);button.setAttribute('role','option');button.setAttribute('aria-selected',String(option.selected));
 roundedSelectPopover.appendChild(button);
}
function enhanceRoundedSelect(select){
 if(select.dataset.roundedSelect==='1')return;
 select.dataset.roundedSelect='1';
 const wrapper=document.createElement('span');wrapper.className='rounded-select-control';select.before(wrapper);wrapper.appendChild(select);
 const trigger=document.createElement('button');trigger.type='button';trigger.className='rounded-select-trigger';
 trigger.innerHTML='<span></span><svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg>';
 wrapper.appendChild(trigger);select.classList.add('rounded-select-native');syncRoundedSelect(select);
 trigger.onclick=event=>{event.preventDefault();event.stopPropagation();if(activeRoundedSelect===select)return closeRoundedSelect();openRoundedSelect(select,trigger)};
 select.addEventListener('change',()=>syncRoundedSelect(select));
 new MutationObserver(()=>syncRoundedSelect(select)).observe(select,{childList:true,subtree:true,attributes:true});
}
roundedSelectPopover.onclick=event=>{
 const option=event.target.closest('.rounded-select-option');if(!option||!activeRoundedSelect)return;
 activeRoundedSelect.value=option.dataset.value;activeRoundedSelect.dispatchEvent(new Event('change',{bubbles:true}));syncRoundedSelect(activeRoundedSelect);closeRoundedSelect();
};
document.querySelectorAll('select').forEach(enhanceRoundedSelect);
new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType!==1)return;if(node.matches?.('select'))enhanceRoundedSelect(node);node.querySelectorAll?.('select').forEach(enhanceRoundedSelect)}))).observe(document.body,{childList:true,subtree:true});
document.addEventListener('click',event=>{if(!roundedSelectPopover.contains(event.target)&&!event.target.closest('.rounded-select-trigger'))closeRoundedSelect()});
document.addEventListener('click',()=>setTimeout(()=>document.querySelectorAll('select').forEach(syncRoundedSelect),0));
document.addEventListener('reset',event=>setTimeout(()=>event.target.querySelectorAll('select').forEach(syncRoundedSelect),0),true);
window.addEventListener('resize',closeRoundedSelect,{passive:true});window.addEventListener('scroll',closeRoundedSelect,{passive:true,capture:true});
